def transform(grid):
    # The 9 markers delimit horizontal runs in rows; fill the gaps/segments
    # adjacent to 9s with color 2, preserving 9s and background 4.
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    for r in range(h):
        # mark each contiguous run of 4 bracketed by 9s? demos color run-of-4 sequences
        # that occur on rows with markers at endpoints; infer horizontal 4 segment between 9 separators
        for c,v in enumerate(grid[r]):
            if v==9:
                continue
        # map 4s to 2 when they are in a row with at least two 9-separated pattern endpoints, demonstrated
    # Vertical markers: in demo, isolated 9 at column 0/13 grow color 2 toward edge or next 9;
    # Transform each horizontal line: runs of 4 adjacent to edge/9 retain; runs between 9 delimiters become 2.
    for r,row in enumerate(grid):
        c=0
        while c<w:
            if row[c]==4:
                e=c
                while e<w and row[e]==4: e+=1
                # In examples coloring occurs on runs of length >=2 following a 9, or from edge,
                # while singletons are left. But rule is horizontal rays from 9 markers across row?
                # Defer model to observed: demo colors contiguous 4s in last row where 9s frame them,
                # and adjacent to top-row 9 boundaries.
                if e-c>=2 and (c==0 or row[c-1]==9):
                    for j in range(c,e): out[r][j]=2
                c=e
            else: c+=1
    # Also color vertically contiguous 4s after leading 9s? demo col 0 rows 2-3? actually 9 above then color 2 below
    for c in range(w):
        r=0
        while r<h:
            if grid[r][c]==4:
                e=r
                while e<h and grid[e][c]==4:e+=1
                if e-r>=2 and (r==0 or grid[r-1][c]==9):
                    for i in range(r,e):out[i][c]=2
                r=e
            else:r+=1
    return out
